package com.example.routepiresfront.data.repository

import com.example.routepiresfront.data.model.Corrida
import com.example.routepiresfront.data.model.Localizacao
import com.example.routepiresfront.data.remote.ApiResponse
import com.example.routepiresfront.data.remote.ApiService
import retrofit2.Response
import java.io.IOException

class CorridaRepository(private val apiService: ApiService) {

    private suspend fun <T> safeApiCall(apiCall: suspend () -> Response<T>): ApiResponse<T> {
        return try {
            val response = apiCall()
            if (response.isSuccessful) {
                val body = response.body()
                if (body != null) {
                    ApiResponse.Success(body)
                } else {
                    @Suppress("UNCHECKED_CAST")
                    ApiResponse.Success(Unit as T) // For successful responses with no body
                }
            } else {
                ApiResponse.Error("Erro: ${response.code()} ${response.message()}", response.code())
            }
        } catch (e: IOException) {
            ApiResponse.Error("Erro de conexão com a internet. Verifique sua rede.")
        } catch (e: Exception) {
            ApiResponse.Error("Ocorreu um erro inesperado: ${e.message}")
        }
    }

    suspend fun getCorridasDisponiveis(mototaxistaId: Long): ApiResponse<List<Corrida>> {
        return safeApiCall { apiService.getCorridasDisponiveis(mototaxistaId) }
    }

    suspend fun aceitarCorrida(corridaId: Long, mototaxistaId: Long): ApiResponse<Corrida> {
        val body = mapOf("mototaxistaId" to mototaxistaId)
        return safeApiCall { apiService.aceitarCorrida(corridaId, body) }
    }

    suspend fun iniciarCorrida(corridaId: Long): ApiResponse<Corrida> {
        return safeApiCall { apiService.iniciarCorrida(corridaId) }
    }

    suspend fun atualizarLocalizacao(corridaId: Long, localizacao: Localizacao): ApiResponse<Unit> {
        return safeApiCall { apiService.atualizarLocalizacao(corridaId, localizacao) }
    }

    suspend fun finalizarCorrida(corridaId: Long): ApiResponse<Corrida> {
        return safeApiCall { apiService.finalizarCorrida(corridaId) }
    }

    suspend fun cancelarCorrida(corridaId: Long, motivo: String?): ApiResponse<Corrida> {
        val body = motivo?.let { mapOf("motivo" to it) }
        return safeApiCall { apiService.cancelarCorrida(corridaId, body) }
    }
}

package com.example.routepiresfront.data.repository

import com.example.routepiresfront.data.model.Corrida
import com.example.routepiresfront.data.model.Localizacao
import com.example.routepiresfront.data.remote.ApiResponse
import com.example.routepiresfront.data.remote.ApiService
import retrofit2.Response
import java.io.IOException

/**
 * REPOSITORY - Camada que conversa com a API REST
 * ● Recebe chamadas do ViewModel
 * ● Retorna dados para o ViewModel (sucesso/erro)
 * ● Contém toda a lógica de obtenção dos dados da API
 * ● Isola a parte de rede do resto do app
 */
class CorridaRepository(private val apiService: ApiService) {

    private suspend fun <T> safeApiCall(apiCall: suspend () -> Response<T>): ApiResponse<T> {
        return try {
            val response = apiCall()
            if (response.isSuccessful) {
                val body = response.body()
                if (body != null) {
                    ApiResponse.Success(body)
                } else {
                    @Suppress("UNCHECKED_CAST")
                    ApiResponse.Success(Unit as T)
                }
            } else {
                ApiResponse.Error("Erro: ${response.code()} ${response.message()}", response.code())
            }
        } catch (e: IOException) {
            ApiResponse.Error("Erro de conexão com a internet. Verifique sua rede.")
        } catch (e: Exception) {
            ApiResponse.Error("Ocorreu um erro inesperado: ${e.message}")
        }
    }

    /**
     * Busca corridas disponíveis para o mototaxista aceitar
     * Usa endpoint de corridas de passageiro como base
     */
    suspend fun getCorridasDisponiveis(mototaxistaId: Long): ApiResponse<List<Corrida>> {
        return safeApiCall { apiService.getCorridasDisponiveis(mototaxistaId) }
    }

    /**
     * Aceita uma corrida (inicia negociação)
     * Atualiza status da corrida para aceita
     */
    suspend fun aceitarCorrida(corridaId: String, mototaxistaId: Long): ApiResponse<Corrida> {
        val body = mapOf(
            "mototaxistaId" to mototaxistaId,
            "status" to "ACEITA"
        )
        return safeApiCall { apiService.aceitarCorrida(corridaId, body) }
    }

    /**
     * Inicia a corrida (mototaxista começa a se deslocar)
     * Atualiza status da corrida para em andamento
     */
    suspend fun iniciarCorrida(corridaId: String): ApiResponse<Corrida> {
        return safeApiCall { apiService.iniciarCorrida(corridaId) }
    }

    /**
     * Atualiza localização do mototaxista durante a corrida
     */
    suspend fun atualizarLocalizacao(corridaId: String, localizacao: Localizacao): ApiResponse<Unit> {
        return safeApiCall { apiService.atualizarLocalizacao(corridaId, localizacao) }
    }

    /**
     * Finaliza a corrida
     * Atualiza status da corrida para finalizada
     */
    suspend fun finalizarCorrida(corridaId: String): ApiResponse<Corrida> {
        return safeApiCall { apiService.finalizarCorrida(corridaId) }
    }

    /**
     * Cancela a corrida
     * Atualiza status e adiciona motivo do cancelamento
     */
    suspend fun cancelarCorrida(corridaId: String, motivo: String?): ApiResponse<Corrida> {
        val body = motivo?.let { mapOf("motivo" to it, "status" to "CANCELADA") }
        return safeApiCall { apiService.cancelarCorrida(corridaId, body) }
    }
}

package com.example.routepiresfront.ui.mototaxista.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.routepiresfront.data.model.Corrida
import com.example.routepiresfront.data.model.Localizacao
import com.example.routepiresfront.data.remote.ApiResponse
import com.example.routepiresfront.data.repository.CorridaRepository
import com.example.routepiresfront.util.SingleLiveEvent
import kotlinx.coroutines.launch

class CorridaMototaxistaViewModel(
    private val repository: CorridaRepository
) : ViewModel() {

    // Construtor sem parâmetros para compatibilidade (cria repository internamente)
    constructor() : this(CorridaRepository(com.example.routepiresfront.data.remote.ApiClient.apiService))

    private val _isLoading = MutableLiveData<Boolean>()
    val isLoading: LiveData<Boolean> = _isLoading

    private val _errorMessage = MutableLiveData<String?>()
    val errorMessage: LiveData<String?> = _errorMessage

    private val _corridasDisponiveis = MutableLiveData<List<Corrida>>()
    val corridasDisponiveis: LiveData<List<Corrida>> = _corridasDisponiveis

    private val _corridaAtual = MutableLiveData<Corrida?>()
    val corridaAtual: LiveData<Corrida?> = _corridaAtual

    val navegarParaNegociacao = SingleLiveEvent<Void>()
    val navegarParaAndamento = SingleLiveEvent<Void>()
    val navegarParaAvaliacao = SingleLiveEvent<Void>()
    val fecharFluxoCorrida = SingleLiveEvent<Void>()

    private var mototaxistaId: Long = 1L // TODO: Obter de um sistema de sessão/autenticação

    fun carregarCorridasDisponiveis() {
        viewModelScope.launch {
            _isLoading.value = true
            when (val response = repository.getCorridasDisponiveis(mototaxistaId)) {
                is ApiResponse.Success -> _corridasDisponiveis.value = response.data
                is ApiResponse.Error -> _errorMessage.value = response.message
                else -> {}
            }
            _isLoading.value = false
        }
    }

    fun selecionarCorrida(corrida: Corrida) {
        _corridaAtual.value = corrida
    }

    fun aceitarCorrida() {
        val corridaId = _corridaAtual.value?.id ?: return
        viewModelScope.launch {
            _isLoading.value = true
            when (val response = repository.aceitarCorrida(corridaId, mototaxistaId)) {
                is ApiResponse.Success -> {
                    _corridaAtual.value = response.data
                    navegarParaNegociacao.call()
                }

                is ApiResponse.Error -> _errorMessage.value = response.message
                else -> {}
            }
            _isLoading.value = false
        }
    }

    fun iniciarCorrida() {
        val corridaId = _corridaAtual.value?.id ?: return
        viewModelScope.launch {
            _isLoading.value = true
            when (val response = repository.iniciarCorrida(corridaId)) {
                is ApiResponse.Success -> {
                    _corridaAtual.value = response.data
                    navegarParaAndamento.call()
                }

                is ApiResponse.Error -> _errorMessage.value = response.message
                else -> {}
            }
            _isLoading.value = false
        }
    }

    fun atualizarLocalizacao(latitude: Double, longitude: Double) {
        val corridaId = _corridaAtual.value?.id ?: return
        val localizacao = Localizacao(latitude, longitude)
        viewModelScope.launch {
            repository.atualizarLocalizacao(corridaId, localizacao)
        }
    }

    fun finalizarCorrida() {
        val corridaId = _corridaAtual.value?.id ?: return
        viewModelScope.launch {
            _isLoading.value = true
            when (val response = repository.finalizarCorrida(corridaId)) {
                is ApiResponse.Success -> {
                    _corridaAtual.value = response.data
                    navegarParaAvaliacao.call()
                }

                is ApiResponse.Error -> _errorMessage.value = response.message
                else -> {}
            }
            _isLoading.value = false
        }
    }

    fun cancelarCorrida(motivo: String? = null) {
        val corridaId = _corridaAtual.value?.id ?: return
        viewModelScope.launch {
            _isLoading.value = true
            when (val response = repository.cancelarCorrida(corridaId, motivo)) {
                is ApiResponse.Success -> {
                    _corridaAtual.value = null
                    fecharFluxoCorrida.call()
                }

                is ApiResponse.Error -> _errorMessage.value = response.message
                else -> {}
            }
            _isLoading.value = false
        }
    }

    fun clearErrorMessage() {
        _errorMessage.value = null
    }

    fun setMototaxistaId(id: Long) {
        mototaxistaId = id
    }
}

